namespace LeoLauncher;
sealed class MediaForm:BarcaWindow
{
    readonly ComboBox sources=new(){DropDownStyle=ComboBoxStyle.DropDownList};readonly Label title=new(),detail=new(),status=new();readonly ActivityOwner activities=new("media-window");ActivityLease? polling;long refreshGeneration;readonly System.Windows.Forms.Timer timer=new(){Interval=5000};readonly Func<string,string,CancellationToken,Task<string>> action;readonly bool preview;bool refreshing,busy,closed;
    public MediaForm(Func<string,string,CancellationToken,Task<string>> execute,bool demo=false)
    {
        action=async(a,v,t)=>{using var request=activities.Begin(a=="media_status"?"refresh":"control",t);try{var result=await execute(a,v,request.Token);request.ThrowIfNotCurrent();return result;}catch(Exception e)when(!request.Current&&FeatureFaults.Recoverable(e)){throw new OperationCanceledException(request.Token);}};preview=demo;Text="Leo · 媒体控制";ClientSize=new(600,435);StartPosition=FormStartPosition.CenterScreen;BackColor=BarcaUi.Canvas;ForeColor=BarcaUi.Text;Font=BarcaUi.Font();var chrome=BarcaUi.Chrome(this,"媒体控制","选择播放器，再直接控制；点歌仍由QQ音乐负责。");
        sources.Bounds=new(24,110,552,33);CompanionUi.ThemeCombo(sources);sources.SelectedIndexChanged+=(_,_)=>{if(sources.SelectedItem is MediaSession item){MediaControl.Service.SelectedId=item.Id;title.Text=item.Title;detail.Text=item.Provider+" · "+(item.Status switch{"Playing"=>"播放中","Paused"=>"已暂停","Stopped"=>"已停止","Opened"=>"已打开","Closed"=>"已关闭","Changing"=>"正在切换",_=>"播放器未提供播放状态"})+"\n"+item.Artist;}};
        title.SetBounds(24,163,552,57);title.Font=BarcaUi.Font(16,true);title.AutoEllipsis=true;detail.SetBounds(24,225,552,48);detail.ForeColor=BarcaUi.Muted;
        var buttons=new FlowLayoutPanel{Bounds=new(24,287,552,40),WrapContents=false};foreach(var (label,command) in new[]{("上一项","previous"),("播放 / 暂停","toggle"),("下一项","next"),("停止","stop")}){var button=new BarcaButton{Text=label,Width=command=="toggle"?150:115,Height=34};button.Click+=async(_,_)=>{if(busy)return;try{busy=true;button.Enabled=false;var selected=sources.SelectedItem as MediaSession??throw new ArgumentException("请先选择播放器");string message=await action("media_"+command,selected.Id,CancellationToken.None);if(closed||IsDisposed)return;status.Text=message;await RefreshSources();}catch(OperationCanceledException){}catch(Exception e){if(!closed&&!IsDisposed&&Visible)status.Text=e.Message;}finally{busy=false;if(!button.IsDisposed)button.Enabled=true;}};buttons.Controls.Add(button);}
        var open=new BarcaButton{Text="打开PotPlayer",Bounds=new(24,342,160,32)};open.Click+=async(_,_)=>{if(busy)return;busy=true;try{if(!preview){string message=await action("media_file","",CancellationToken.None);if(closed||IsDisposed)return;status.Text=message;}await RefreshSources();}catch(OperationCanceledException){}catch(Exception e){if(!closed&&!IsDisposed&&Visible)status.Text=e.Message;}finally{busy=false;}};
        var file=new BarcaButton{Text="选择媒体文件…",Bounds=new(195,342,185,32)};file.Click+=async(_,_)=>{if(preview||busy)return;using var picker=new OpenFileDialog{Title="用PotPlayer打开媒体",Filter="媒体文件|*.mp4;*.mkv;*.avi;*.mov;*.mp3;*.flac;*.wav;*.m3u;*.m3u8|所有文件|*.*"};if(picker.ShowDialog(this)==DialogResult.OK)try{if(busy)return;busy=true;string message=await action("media_file",picker.FileName,CancellationToken.None);if(closed||IsDisposed)return;status.Text=message;await RefreshSources();}catch(OperationCanceledException){}catch(Exception e){if(!closed&&!IsDisposed&&Visible)status.Text=e.Message;}finally{busy=false;}};
        var refresh=new BarcaButton{Text="刷新",Bounds=new(460,342,116,32)};refresh.Click+=async(_,_)=>await RefreshSources();status.SetBounds(24,386,552,35);status.ForeColor=BarcaUi.Muted;status.Font=BarcaUi.Font(8.5f);Controls.AddRange([sources,title,detail,buttons,open,file,refresh,status,chrome]);MinimumSize=MaximumSize=Size;VisibleChanged+=(_,_)=>UpdatePolling();timer.Tick+=async(_,_)=>{if(Visible&&!busy&&!closed)await RefreshSources();};
    }
    async Task RefreshSources(){if(refreshing||IsDisposed||closed)return;refreshing=true;long generation=++refreshGeneration;try{var rows=preview?new[]{new MediaSession("potplayer:preview","PotPlayer","示例视频","","Unknown")}:System.Text.Json.JsonSerializer.Deserialize<MediaSession[]>(await action("media_status","",CancellationToken.None))??[];if(IsDisposed||closed||generation!=refreshGeneration)return;string selected=(sources.SelectedItem as MediaSession)?.Id??MediaControl.Service.SelectedId;sources.BeginUpdate();sources.Items.Clear();sources.Items.AddRange(rows);sources.SelectedItem=rows.FirstOrDefault(s=>s.Id==selected)??rows.FirstOrDefault(s=>s.Status=="Playing")??rows.FirstOrDefault();sources.EndUpdate();if(rows.Length==0){title.Text="尚无可控制的播放器";detail.Text="先打开PotPlayer选择视频，或在QQ音乐播放歌曲。";if(MediaControl.Service.LastError!=null)status.Text="Windows媒体接口："+MediaControl.Service.LastError;}else if(status.Text.Length==0)status.Text="已连接本机媒体接口 · 不调用模型 API";}catch(OperationCanceledException){}catch(Exception e){if(!closed&&!IsDisposed&&Visible)status.Text=e.Message+" · 可点击刷新重试";}finally{if(generation==refreshGeneration)refreshing=false;}}
    void UpdatePolling()
    {
        if(closed)return;
        if(Visible){polling??=activities.Begin("polling");timer.Start();_=RefreshSources();}
        else{timer.Stop();polling?.Dispose();polling=null;refreshGeneration++;refreshing=false;activities.Reset();}
    }
    protected override void Dispose(bool disposing){if(disposing&&!closed){closed=true;timer.Stop();timer.Dispose();polling?.Dispose();polling=null;activities.Dispose();}base.Dispose(disposing);}
}
sealed partial class PetForm
{
    MediaForm? mediaWindow;
    async void ShowMedia(){try{await commands.ExecuteAsync(new("media_open","","media-shortcut"));}catch(OperationCanceledException){}catch(Exception e)when(FeatureFaults.Recoverable(e)){if(!IsDisposed)OperationFeedback.Error(e.Message);}}
    void ShowMediaCore(){Modules.Require(prefs,"media");if(mediaWindow==null||mediaWindow.IsDisposed){mediaWindow=new MediaForm((a,v,t)=>commands.ExecuteAsync(new(a,v,"media-ui"),t),previewMode);mediaWindow.FormClosed+=(_,_)=>presentation.Invalidate(ModuleWindowTarget.Media);}if(!mediaWindow.Visible)WindowPositions.Prepare(mediaWindow,"media",Bounds,previewMode);WindowInteraction.Show(mediaWindow);}
}
